fn tamanho(s: &String) -> usize {
    s.len() // apenas lê, não toma posse
}

fn somar_um(n: &mut i32) {
    *n += 1; // '*' desreferencia &mut i32 para alterar o valor original
}

fn main() {
    let texto = String::from("Rust");
    println!("Tam: {}", tamanho(&texto));
    let mut pontos = 10;
    somar_um(&mut pontos);
}

